/**
 * Categorizes the compliance record based on its origin.
 *
 * This discriminator determines how the record was created:
 *
 * - USER_REPORT: Generated when a citizen submits a report against content or
 *   another user
 * - MODERATOR_ACTION: Created when a moderator takes action (removal, warning,
 *   ban, etc.)
 * - SYSTEM_TRIGGER: Automated record generated by system rules (e.g., spam
 *   detection, rate limiting)
 * - APPEAL: Generated when a user appeals a moderation decision
 *
 * The record_type directly influences which related entities are linked to this
 * compliance record and determines the visibility and processing workflow for
 * the record.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IComplianceRecordType =
  | "USER_REPORT"
  | "MODERATOR_ACTION"
  | "SYSTEM_TRIGGER"
  | "APPEAL";
